item.aggregated_output:
    const chunk = Buffer.isBuffer(part) ? part : Buffer.from(part);
    size += chunk.length;
    if (size > 1_000_000) throw new Error('body too large');
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf8');
}

const server = createServer(async (req, res) => {
  const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const beat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE singleton=1').get() as {seen_at: number} | undefined;
    return send(res, 200, { status: 'ok', worker: beat && Date.now() - beat.seen_at <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (req.method !== 'POST') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const fields: {field: string; message: string}[] = [];
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    const key = req.headers['idempotency-key'];
    const idemKey = Array.isArray(key) ? key[0] : key;
    if (idemKey !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(idemKey)) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, numbers, underscores, or hyphens.' });
    let raw: string;
    try { raw = await readBody(req); } catch { fields.push({field: 'body', message: 'Request body is too large.'}); raw = ''; }
    let body: unknown;
    if (!raw) { if (!fields.some(f => f.field === 'body')) fields.push({field:'body', message:'A JSON object is required.'}); }
    else {
      try { body = JSON.parse(raw); } catch { fields.push({ field: 'body', message: 'Malformed JSON.' }); }
    }
    if (!fields.some(f => f.field === 'body' && (f.message === 'Malformed JSON.' || f.message === 'A JSON object is required.')) && body !== undefined) {
      if (typeof body !== 'object' || body === null || Array.isArray(body)) fields.push({field: 'body', message: 'Must be a JSON object.'});
      else {
        const value = body as Record<string, unknown>;
        for (const name of Object.keys(value)) if (!['input','steps','failAttempts'].includes(name)) fields.push({field:name, message:'Unknown field.'});
        if (typeof value.input !== 'string') fields.push({field:'input', message:'Must be a string.'});
        else {
          if (value.input.length < 1 || value.input.length > 1000) fields.push({field:'input', message:'Must contain 1–1000 characters.'});
          if (!value.input.trim()) fields.push({field:'input', message:'Must not be only whitespace.'});
        }
        if (value.steps !== undefined && (!Number.isInteger(value.steps) || (value.steps as number) < 1 || (value.steps as number) > 20)) fields.push({field:'steps', message:'Must be an integer from 1 to 20.'});
        if (value.failAttempts !== undefined && (!Number.isInteger(value.failAttempts) || (value.failAttempts as number) < 0 || (value.failAttempts as number) > 5)) fields.push({field:'failAttempts', message:'Must be an integer from 0 to 5.'});
      }
    }
    if (fields.length) return error(res, 400, 'invalid_request', 'The request is invalid.', fields);
    const value = body as {input:string; steps?:number; failAttempts?:number};
    const payload = JSON.stringify({input:value.input, steps:value.steps ?? 5, failAttempts:value.failAttempts ?? 0});
    const now = new Date().toISOString();
    const create = db.prepare('INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,result,error,created_at,updated_at,next_attempt_at) VALUES (?,\'queued\',?,?,?,0,0,NULL,NULL,?,?,0)');
    try {
      db.exec('BEGIN IMMEDIATE');
      if (idemKey !== undefined) {
        const prior = db.prepare('SELECT i.payload,j.* FROM idempotency i JOIN jobs j ON j.id=i.job_id WHERE i.key=?').get(idemKey) as ({payload:string} & JobRow) | undefined;
        if (prior) {
          db.exec('COMMIT');
          if (prior.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was used with a different payload.');
          return send(res, 200, toJob(prior));
        }
      }
      const id = randomUUID();
      create.run(id, value.input, value.steps ?? 5, value.failAttempts ?? 0, now, now);
      if (idemKey !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(idemKey, payload, id);
      db.exec('COMMIT');
      const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as unknown as JobRow;
      return send(res, 201, toJob(row));
    } catch (e) {
      try { db.exec('ROLLBACK'); } catch { /* transaction already closed */ }
      console.error('submission failed', e);
      return error(res, 500, 'internal_error', 'Could not create the job.');
    }
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string; try { id = decodeURIComponent(match[1]!); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as unknown as JobRow | undefined;
    return row ? send(res, 200, toJob(row)) : error(res, 404, 'not_found', 'Job not found.');
  }
  return error(res, 404, 'not_found', 'Route not found.');
});
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
